SET NOCOUNT ON;
SELECT DB_NAME() AS database_name,SUSER_SNAME() AS control_identity,SCHEMA_ID(N'app') AS app_schema_id;
SELECT p.name,p.type_desc,p.authentication_type_desc,r.name AS role_name
 FROM sys.database_principals p LEFT JOIN sys.database_role_members m ON m.member_principal_id=p.principal_id
 LEFT JOIN sys.database_principals r ON r.principal_id=m.role_principal_id
 WHERE p.name IN (N'orderops_investigator',N'dia-investigator-round19') ORDER BY p.name,r.name;
SELECT OBJECT_ID(N'app.round22_access_rows') AS rows_id,OBJECT_ID(N'app.round22_access_readers') AS readers_id,OBJECT_ID(N'app.round22_access_export') AS export_id;
